JavaScriptTypeScript <pre><code>const todoStore = TodoModel.create({
    // Initial state (validated against schema)
    state: {
        todos: [],
        filter: "all",
    },
    // Synchronous actions
    actions: {
        add: ({ state, payload }) =&gt; {
            state.todos.push(payload);
        },
        remove: ({ state, payload }) =&gt; {
            state.todos = state.todos.filter(t =&gt; t.id !== payload.id);
        },
    },
    // Async actions (thunks)
    asyncActions: {
        loadTodos: async ({ dispatch, query }) =&gt; {
            await query("fetchTodos");
        },
    },
    // State machines
    machines: {
        filter: {
            showAll: { from: { filter: "active" }, to: { filter: "all" } },
            showActive: { from: { filter: "all" }, to: { filter: "active" } },
        },
    },
    // Queries
    queries: {
        fetchTodos: {
            queryKey: ["todos"],
            queryFn: () =&gt; fetch("/api/todos").then(r =&gt; r.json()),
            onSuccess: ({ data, dispatch }) =&gt; {
                dispatch("setTodos", data);
            },
        },
    },
    // Mutations
    mutations: {
        createTodo: {
            mutationFn: (todo) =&gt; fetch("/api/todos", {
                method: "POST",
                body: JSON.stringify(todo),
            }).then(r =&gt; r.json()),
            onSuccess: ({ invalidateQueries }) =&gt; {
                invalidateQueries({ queryKey: ["todos"] });
            },
        },
    },
    // Action specifications
    specs: {
        add: {
            precondition: ({ payload }) =&gt; {
                return payload?.text?.length &gt; 0;
            },
        },
    },
    // Memoized values
    memos: {
        activeTodos: ({ state }) =&gt; {
            return state.todos.filter(t =&gt; !t.done);
        },
        completedCount: ({ state }) =&gt; {
            return state.todos.filter(t =&gt; t.done).length;
        },
    },
    // Store options
    options: {
        enableLogging: true,
    },
});
</code></pre> <pre><code>const todoStore = TodoModel.create({
