              &lt;span style=${todo.done ? "text-decoration: line-through" : ""}&gt;
                ${todo.text}
              &lt;/span&gt;
              &lt;button @click=${() =&gt; TodoStore.dispatch("removeTodo", { id: todo.id })}&gt;
                ×
              &lt;/button&gt;
            &lt;/li&gt;
          `)}
        &lt;/ul&gt;

        &lt;p&gt;&lt;em&gt;Todos persist across page refreshes.&lt;/em&gt;&lt;/p&gt;
      &lt;/div&gt;
