      &lt;input type="range" min="0" max="30" .value=${String(this.duration)} @input=${(event: InputEvent) =&gt; this.updateDuration(event)}&gt;
      &lt;button @click=${() =&gt; this.resetTimer()}&gt;Reset&lt;/button&gt;
