  onFetch: ({ dispatch }) =&gt; dispatch('todos:setPending'),
  onSuccess: ({ data, dispatch }) =&gt; dispatch('todos:setSuccess', data),
  onError: ({ error, dispatch }) =&gt; dispatch('todos:setError', error),
})

TodoStore.defineMutation&lt;NewTodo, Todo&gt;('todos:create', {
